// PATTERN BANK: Acid 303 Bass
// Classic squelchy acid line for breakdowns
setcps(138/60/4)
let acidFilter = slider(800, 200, 4000, 10, "ACID Filter")
let acidRes = slider(18, 5, 25, 0.5, "ACID Resonance")
let acidVol = slider(0.6, 0, 1, 0.01, "ACID Volume")

let acid = note("<a2 a2 c3 a2 e2 e2 g2 e2>")
  .s("sawtooth")
  .cutoff(sine.range(300, acidFilter).fast(2))
  .resonance(acidRes)
  .decay(0.15)
  .sustain(0)
  .gain(acidVol)
  .struct("x x [x x] x x [~ x] x x")

let kick = s("bd").bank("RolandTR909").gain(1.1).struct("x x x x")
let hats = s("hh").bank("RolandTR909").gain(0.4).struct("~ x ~ x ~ x ~ x")

stack(kick, hats, acid)

// DJ OPUS - SECTION 6: SECOND DROP - ACID EUPHORIA
// Everything at once. 303 meets diva meets galactic pads.
setcps(138/60/4)

let masterFilter = slider(3000, 500, 12000, 10, "MASTER Filter")
let acidIntensity = slider(0.5, 0, 0.8, 0.01, "ACID Intensity")
let divaVol = slider(0.4, 0, 0.7, 0.01, "DIVA Voice")
let leadVol = slider(0.35, 0, 0.6, 0.01, "LEAD Melody")

// KICK - full power
let kick = s("bd").bank("RolandTR909")
  .gain(1.15)
  .struct("x x x x")

// CLAP
let clap = s("cp").bank("RolandTR909")
  .gain(0.75)
  .struct("~ x ~ x")
  .room(0.25)

// HATS - driving
let hats = s("hh").bank("RolandTR909")
  .gain(0.45)
  .struct("~ x ~ x ~ x ~ x")
  .cutoff(masterFilter)

// OPEN HAT
let oh = s("oh").bank("RolandTR909")
  .gain(0.35)
  .struct("~ ~ ~ ~ ~ ~ x ~")

// ACID 303 - squelching underneath
let acid = note("<a2 a2 c3 a2 e2 e2 g2 e2>")
  .s("sawtooth")
  .cutoff(sine.range(300, 3000).fast(2))
  .resonance(20)
  .decay(0.15)
  .sustain(0)
  .gain(acidIntensity)
  .struct("x x [x x] x x [~ x] x x")

// DIVA - voice oohs soaring above
let diva = note("<[a3,e4] [e3,b3] [f3,c4] [d3,a3]>".slow(2))
  .s("gm_voice_oohs")
  .gain(divaVol)
  .room(0.85)
  .size(0.9)
  .vowel("<a e i o>".slow(4))

// SYNTH CHOIR - backing
let choir = note("<[a3,c4,e4] [e3,g3,b3] [f3,a3,c4] [d3,f3,a3]>".slow(2))
  .s("gm_synth_choir")
  .gain(divaVol.mul(0.5))
  .room(0.8)

// GALACTIC PAD - still holding it all together
let galactic = note("<[a2,e3,a3] [e2,b2,e3] [f2,c3,f3] [d2,a2,d3]>".slow(2))
  .s("gm_pad_sweep")
  .gain(0.25)
  .cutoff(perlin.range(400, 2500).slow(16))
  .room(0.9)
  .size(0.95)

// LEAD - emotional supersaw melody
let lead = note("a4 ~ c5 ~ e5 ~ a5 e5 ~ c5 a4 ~ e4 ~ a4 ~")
  .s("sawtooth")
  .superimpose(x => x.add(0.08))
  .superimpose(x => x.add(-0.08))
  .cutoff(masterFilter)
  .resonance(4)
  .decay(0.4)
  .sustain(0.15)
  .gain(leadVol)
  .delay(0.4)
  .delaytime(3/8)
  .delayfeedback(0.35)
  .room(0.6)
  .jux(rev)

// CRASH
let crash = s("oh").bank("RolandTR909")
  .speed(0.4)
  .gain(0.45)
  .room(0.9)
  .struct("x ~ ~ ~ ~ ~ ~ ~")
  .slow(4)

stack(kick, clap, hats, oh, acid, diva, choir, galactic, lead, crash)

// DJ OPUS - SECTION 4: THE BREAKDOWN
// Everything drops out. Just the voice and the void.
setcps(138/60/4)

let breakFilter = slider(800, 200, 8000, 10, "BREAK Filter")
let divaSwell = slider(0.5, 0, 0.7, 0.01, "DIVA Swell")

// Diva voice - exposed, emotional
let diva = note("<[a3,e4] [f3,c4] [d3,a3] [e3,b3]>".slow(4))
  .s("gm_voice_oohs")
  .gain(divaSwell)
  .room(0.95)
  .size(0.95)
  .cutoff(breakFilter)
  .vowel("<a e i o>".slow(8))

// Pad sweep - vast emptiness
let sweep = note("<[a2,e3,a3] [f2,c3,f3] [d2,a2,d3] [e2,b2,e3]>".slow(4))
  .s("gm_pad_sweep")
  .gain(0.3)
  .cutoff(perlin.range(300, 2000).slow(16))
  .room(1)
  .size(1)

// Crystal fx - distant stars
let crystal = note("a5 ~ ~ ~ e5 ~ ~ ~".slow(2))
  .s("gm_fx_crystal")
  .gain(0.1)
  .delay(0.7)
  .delaytime(0.5)
  .delayfeedback(0.6)
  .room(1)

// Atmosphere halo
let halo = note("<a4 f4 d4 e4>".slow(4))
  .s("gm_pad_halo")
  .gain(0.2)
  .room(0.95)
  .size(0.95)

stack(diva, sweep, crystal, halo)

// DJ OPUS - EPIC TRANCE SET
// Section 3: THE DROP - Full Euphoria
setcps(138/60/4)

// === YOUR SLIDERS ===
let masterVol = slider(0.8, 0, 1, 0.01, "MASTER Volume")
let choirVol = slider(0.8, 0, 0.8, 0.01, "DIVA CHOIR")
let leadVol = slider(0.5, 0, 0.8, 0.01, "SUPERSAW Lead")
let filterOpen = slider(4000, 500, 12000, 10, "FILTER Open")
let stereoWidth = slider(0.5, 0, 1, 0.01, "STEREO Width")
let energy = slider(0.7, 0, 1, 0.01, "ENERGY Level")

// KICK - full power four on the floor
let kick = s("bd").bank("RolandTR909")
  .gain(1.2)
  .struct("x x x x")

// CLAP on 2 and 4
let clap = s("cp").bank("RolandTR909")
  .gain(0.8)
  .struct("~ x ~ x")
  .room(0.25)

// OFFBEAT HATS - driving
let hats = s("hh").bank("RolandTR909")
  .gain(energy.mul(0.6))
  .struct("~ x ~ x ~ x ~ x")
  .cutoff(filterOpen)

// OPEN HAT accents
let oh = s("oh").bank("RolandTR909")
  .gain(0.4)
  .struct("~ ~ ~ ~ ~ ~ x ~")

// SUPERSAW BASS - fat rolling line
let bass = note("<a2 a2 e2 e2 f2 f2 d2 d2>")
  .s("sawtooth")
  .superimpose(x => x.add(0.08))
  .cutoff(sine.range(400, 2200).slow(4))
  .resonance(14)
  .decay(0.2)
  .sustain(0.08)
  .gain(energy.mul(0.7))
  .struct("x ~ x x ~ x x ~")

// DIVA CHOIR - the moment
let choir = note("<[a3,e4,c5] [e3,b3,g4] [f3,c4,a4] [d3,a3,f4]>".slow(2))
  .s("gm_choir_aahs")
  .gain(choirVol)
  .cutoff(filterOpen)
  .room(0.85)
  .size(0.9)
  .vowel("<a e i o>".slow(4))

// SUPERSAW LEAD - euphoric melody
let lead = note("a4 ~ c5 e5 ~ a5 e5 c5")
  .s("sawtooth")
  .superimpose(x => x.add(0.1))
  .superimpose(x => x.add(-0.1))
  .cutoff(filterOpen)
  .resonance(6)
  .decay(0.3)
  .sustain(0.15)
  .gain(leadVol)
  .delay(0.4)
  .delaytime(3/16)
  .delayfeedback(0.45)
  .room(0.5)
  .jux(rev)

// TRANCE ARP - cascading
let arp = note("a4 c5 e5 a5 c6 a5 e5 c5")
  .s("triangle")
  .cutoff(filterOpen.mul(0.8))
  .resonance(12)
  .decay(0.1)
  .sustain(0)
  .gain(energy.mul(0.3))
  .delay(0.5)
  .delaytime(3/16)
  .delayfeedback(0.55)
  .room(0.4)

// PAD - wide atmospheric bed
let pad = note("<[a3,e4] [e3,b3] [f3,c4] [d3,a3]>".slow(2))
  .s("sawtooth")
  .superimpose(x => x.add(0.05))
  .cutoff(filterOpen.mul(0.6))
  .resonance(5)
  .attack(1.2)
  .decay(2)
  .sustain(0.5)
  .release(2)
  .gain(0.25)
  .room(0.9)
  .size(0.95)

// CRASH on beat 1 every 4 bars
let crash = s("oh").bank("RolandTR909")
  .speed(0.5)
  .gain(0.5)
  .room(0.8)
  .struct("x ~ ~ ~ ~ ~ ~ ~")
  .slow(4)

stack(kick, clap, hats, oh, bass, choir, lead, arp, pad, crash)
  .gain(masterVol)

// DJ OPUS - SECTION 3: GALACTIC EUPHORIA
// Robert Miles x ATB x Adagio vibes
setcps(138/60/4)

// === SLIDERS ===
let divaVol = slider(0, 0, 0.7, 0.01, "DIVA Voice")
let padDepth = slider(0.3, 0, 0.7, 0.01, "PAD Depth")
let sweepFilter = slider(1200, 200, 8000, 10, "SWEEP Filter")
let leadVol = slider(0, 0, 0.6, 0.01, "LEAD Melody")
let bassVol = slider(0.5, 0, 0.8, 0.01, "BASS Drive")
let atmosphere = slider(0.7, 0, 1, 0.01, "ATMOSPHERE")

// KICK - solid foundation
let kick = s("bd").bank("RolandTR909")
  .gain(1.1)
  .struct("x x x x")

// CLAP
let clap = s("cp").bank("RolandTR909")
  .gain(0.7)
  .struct("~ x ~ x")
  .room(0.3)

// HATS - subtle offbeat
let hats = s("hh").bank("RolandTR909")
  .gain(0.4)
  .struct("~ x ~ x ~ x ~ x")
  .cutoff(3000)

// DIVA VOICE - voice oohs, slow and wide
let diva = note("<[a3,e4] [e3,b3] [f3,c4] [d3,a3]>".slow(4))
  .s("gm_voice_oohs")
  .gain(divaVol)
  .room(0.9)
  .size(0.95)
  .cutoff(sweepFilter)

// SYNTH CHOIR - layered underneath
let choir = note("<[a3,c4,e4] [e3,g3,b3] [f3,a3,c4] [d3,f3,a3]>".slow(4))
  .s("gm_synth_choir")
  .gain(divaVol.mul(0.6))
  .room(0.85)
  .size(0.9)

// GALACTIC PAD - massive sweep pad
let galacticPad = note("<[a2,e3,a3] [e2,b2,e3] [f2,c3,f3] [d2,a2,d3]>".slow(4))
  .s("gm_pad_sweep")
  .gain(padDepth)
  .cutoff(perlin.range(400, 3000).slow(16))
  .room(atmosphere)
  .size(atmosphere)

// HALO PAD - ethereal upper layer
let haloPad = note("<a4 e4 f4 d4>".slow(4))
  .s("gm_pad_halo")
  .gain(padDepth.mul(0.4))
  .room(0.95)
  .size(0.95)
  .cutoff(sweepFilter)

// DEEP BASS - sawtooth with organic filter drift
let bass = note("<a1 a1 e1 e1 f1 f1 d1 d1>")
  .s("sawtooth")
  .cutoff(perlin.range(200, 1200).slow(8))
  .resonance(10)
  .decay(0.25)
  .sustain(0.1)
  .gain(bassVol)
  .struct("x ~ x x ~ x x ~")

// LEAD - simple, emotional, low in the mix
let lead = note("~ a4 ~ e4 ~ c5 ~ a4")
  .s("sawtooth")
  .superimpose(x => x.add(0.08))
  .superimpose(x => x.add(-0.08))
  .cutoff(sweepFilter)
  .resonance(4)
  .decay(0.5)
  .sustain(0.2)
  .gain(leadVol)
  .delay(0.45)
  .delaytime(3/8)
  .delayfeedback(0.4)
  .room(0.7)

// ATMOSPHERE FX - distant sparkle
let fx = note("a5 ~ ~ e5 ~ ~ c5 ~".slow(2))
  .s("gm_fx_crystal")
  .gain(atmosphere.mul(0.15))
  .room(1)
  .size(1)
  .delay(0.6)
  .delaytime(0.5)
  .delayfeedback(0.5)

stack(kick, clap, hats, diva, choir, galacticPad, haloPad, bass, lead, fx)

// DJ OPUS - THE MEGA MIX
// One pattern to rule them all. YOU control the transitions.
// Breakdown -> Rise -> Drop all lives here. Ride the sliders.
setcps(138/60/4)

// === SECTION CONTROLS ===
let kickVol = slider(0, 0, 1, 0.01, "KICK")
let bassVol = slider(0, 0, 0.7, 0.01, "BASS")
let hatVol = slider(0, 0, 0.6, 0.01, "HATS")
let clapVol = slider(0, 0, 0.7, 0.01, "CLAP")
let acidVol = slider(0, 0, 0.7, 0.01, "ACID 303")
let leadVol = slider(0, 0, 0.5, 0.01, "LEAD")
let padVol = slider(0.3, 0, 0.6, 0.01, "PAD")
let sweepFilter = slider(1200, 200, 12000, 10, "FILTER SWEEP")

// KICK - four on the floor
let kick = s("bd").bank("RolandTR909")
  .gain(kickVol)
  .struct("x x x x")

// CLAP on 2 and 4
let clap = s("cp").bank("RolandTR909")
  .gain(clapVol)
  .struct("~ x ~ x")
  .room(0.25)

// OFFBEAT HATS
let hats = s("hh").bank("RolandTR909")
  .gain(hatVol)
  .struct("~ x ~ x ~ x ~ x")

// OPEN HAT accent
let oh = s("oh").bank("RolandTR909")
  .gain(hatVol)
  .struct("~ ~ ~ ~ ~ ~ x ~")

// DEEP BASS - rolling sawtooth with organic drift
let bass = note("<a2 a2 e2 e2 f2 f2 d2 d2>")
  .s("sawtooth")
  .cutoff(perlin.range(200, 1800).slow(8))
  .resonance(12)
  .decay(0.25)
  .sustain(0.08)
  .gain(bassVol)
  .struct("x ~ x x ~ x x ~")

// ACID 303 - squelchy
let acid = note("<a2 a2 c3 a2 e2 e2 g2 e2>")
  .s("sawtooth")
  .cutoff(sine.range(300, 3000).fast(2))
  .resonance(20)
  .decay(0.15)
  .sustain(0)
  .gain(acidVol)
  .struct("x x [x x] x x [~ x] x x")

// PAD SWEEP - galactic bed
let pad = note("<[a2,e3,a3] [e2,b2,e3] [f2,c3,f3] [d2,a2,d3]>".slow(2))
  .s("sawtooth")
  .cutoff(perlin.range(400, 2500).slow(16))
  .resonance(6)
  .attack(1.2)
  .decay(2)
  .sustain(0.5)
  .release(2)
  .gain(padVol)
  .room(0.9)
  .size(0.95)

// VOCAL PAD - sawtooth with vowel filter for diva texture
let vocalPad = note("<[a3,e4] [e3,b3] [f3,c4] [d3,a3]>".slow(2))
  .s("sawtooth")
  .vowel("<a e i o>".slow(4))
  .cutoff(sweepFilter)
  .resonance(8)
  .attack(0.8)
  .decay(1.5)
  .sustain(0.6)
  .release(2)
  .gain(padVol)
  .room(0.85)
  .size(0.9)

// LEAD - emotional supersaw
let lead = note("a4 ~ c5 ~ e5 ~ a5 e5 ~ c5 a4 ~ e4 ~ a4 ~")
  .s("sawtooth")
  .superimpose(x => x.add(0.08))
  .superimpose(x => x.add(-0.08))
  .cutoff(sweepFilter)
  .resonance(4)
  .decay(0.4)
  .sustain(0.15)
  .gain(leadVol)
  .delay(0.4)
  .delaytime(3/8)
  .delayfeedback(0.35)
  .room(0.6)
  .jux(rev)

// CRYSTAL FX - distant sparkle always present
let crystal = note("a5 ~ ~ ~ e5 ~ ~ ~".slow(2))
  .s("gm_fx_crystal")
  .gain(0.08)
  .delay(0.7)
  .delaytime(0.5)
  .delayfeedback(0.5)
  .room(1)

stack(kick, clap, hats, oh, bass, acid, pad, vocalPad, lead, crystal)

// DJ OPUS - MEGA MIX v2
// Robert Miles - Children vibes. Clean. Dreamy. Space.
// All transitions via sliders. No hard cuts.
setcps(138/60/4)

// === YOUR DECK ===
let kickVol = slider(0.8, 0, 1.1, 0.01, "KICK")
let bassVol = slider(0.4, 0, 0.7, 0.01, "BASS")
let hatVol = slider(0.3, 0, 0.5, 0.01, "HATS")
let pianoVol = slider(0.4, 0, 0.6, 0.01, "PIANO Lead")
let padVol = slider(0.3, 0, 0.5, 0.01, "PAD Depth")
let sweepFilter = slider(2000, 200, 10000, 10, "FILTER SWEEP")
let acidVol = slider(0, 0, 0.6, 0.01, "ACID 303")
let delayMix = slider(0.3, 0, 0.7, 0.01, "DELAY Wash")

// KICK - clean four on the floor
let kick = s("bd").bank("RolandTR909")
  .gain(kickVol)
  .struct("x x x x")

// CLAP - subtle
let clap = s("cp").bank("RolandTR909")
  .gain(0.5)
  .struct("~ x ~ x")
  .room(0.2)

// HATS - gentle offbeat
let hats = s("hh").bank("RolandTR909")
  .gain(hatVol)
  .struct("~ x ~ x ~ x ~ x")

// BASS - simple, deep, rolling
let bass = note("<a1 a1 e1 e1 f1 f1 d1 d1>".slow(2))
  .s("sawtooth")
  .cutoff(perlin.range(200, 1200).slow(8))
  .resonance(10)
  .decay(0.3)
  .sustain(0.1)
  .gain(bassVol)

// PIANO LEAD - the Robert Miles moment
// Dreamy melody with delay, lots of space
let piano = note("a4 ~ e5 c5 ~ ~ a4 ~ ~ e4 a4 c5 ~ e5 ~ ~".slow(2))
  .s("triangle")
  .cutoff(sweepFilter)
  .resonance(2)
  .attack(0.01)
  .decay(0.6)
  .sustain(0.1)
  .gain(pianoVol)
  .delay(delayMix)
  .delaytime(3/8)
  .delayfeedback(0.45)
  .room(0.6)

// PAD - warm sawtooth bed, simple
let pad = note("<[a2,e3] [e2,b2] [f2,c3] [d2,a2]>".slow(4))
  .s("sawtooth")
  .cutoff(perlin.range(300, 2000).slow(16))
  .resonance(5)
  .attack(1.5)
  .decay(2)
  .sustain(0.5)
  .release(2)
  .gain(padVol)
  .room(0.85)
  .size(0.9)

// ACID - bring in when you want edge
let acid = note("<a2 a2 c3 a2 e2 e2 g2 e2>")
  .s("sawtooth")
  .cutoff(sine.range(300, 2500).fast(2))
  .resonance(18)
  .decay(0.15)
  .sustain(0)
  .gain(acidVol)
  .struct("x x [x x] x x [~ x] x x")

stack(kick, clap, hats, bass, piano, pad, acid)

// DJ OPUS - MEGA MIX v3
// Robert Miles vibes + real vocals
setcps(138/60/4)

samples('shabda:choir:6,vocal:4,diva:4,female voice:3')

// === YOUR DECK ===
let kickVol = slider(0.8, 0, 1.1, 0.01, "KICK")
let bassVol = slider(0.4, 0, 0.7, 0.01, "BASS")
let hatVol = slider(0.3, 0, 0.5, 0.01, "HATS")
let pianoVol = slider(0.4, 0, 0.6, 0.01, "PIANO Lead")
let padVol = slider(0.3, 0, 0.5, 0.01, "PAD Depth")
let sweepFilter = slider(2000, 200, 10000, 10, "FILTER SWEEP")
let vocalVol = slider(0.4, 0, 0.8, 0.01, "VOCALS")
let delayMix = slider(0.3, 0, 0.7, 0.01, "DELAY Wash")

// KICK
let kick = s("bd").bank("RolandTR909")
  .gain(kickVol)
  .struct("x x x x")

// CLAP
let clap = s("cp").bank("RolandTR909")
  .gain(0.5)
  .struct("~ x ~ x")
  .room(0.2)

// HATS
let hats = s("hh").bank("RolandTR909")
  .gain(hatVol)
  .struct("~ x ~ x ~ x ~ x")

// BASS
let bass = note("<a1 a1 e1 e1 f1 f1 d1 d1>".slow(2))
  .s("sawtooth")
  .cutoff(perlin.range(200, 1200).slow(8))
  .resonance(10)
  .decay(0.3)
  .sustain(0.1)
  .gain(bassVol)

// PIANO LEAD - dreamy
let piano = note("a4 ~ e5 c5 ~ ~ a4 ~ ~ e4 a4 c5 ~ e5 ~ ~".slow(2))
  .s("triangle")
  .cutoff(sweepFilter)
  .resonance(2)
  .attack(0.01)
  .decay(0.6)
  .sustain(0.1)
  .gain(pianoVol)
  .delay(delayMix)
  .delaytime(3/8)
  .delayfeedback(0.45)
  .room(0.6)

// PAD - warm bed
let pad = note("<[a2,e3] [e2,b2] [f2,c3] [d2,a2]>".slow(4))
  .s("sawtooth")
  .cutoff(perlin.range(300, 2000).slow(16))
  .resonance(5)
  .attack(1.5)
  .decay(2)
  .sustain(0.5)
  .release(2)
  .gain(padVol)
  .room(0.85)
  .size(0.9)

// CHOIR - slow cycling through samples with reverb
let choirVox = s("<choir:0 choir:1 choir:2 choir:3 choir:4 choir:5>".slow(4))
  .gain(vocalVol)
  .room(0.9)
  .size(0.9)
  .cutoff(sweepFilter)
  .speed(0.8)

// DIVA - layered on top
let divaVox = s("<diva:0 diva:1>".slow(8))
  .gain(vocalVol)
  .room(0.85)
  .size(0.9)
  .speed(0.7)

// VOCAL hits
let vocalHit = s("<vocal:0 vocal:1 vocal:2 vocal:3>".slow(2))
  .gain(vocalVol)
  .room(0.7)
  .delay(0.4)
  .delaytime(3/8)
  .delayfeedback(0.35)
  .speed(0.9)

stack(kick, clap, hats, bass, piano, pad, choirVox, divaVox, vocalHit)

// PATTERN BANK: Progressive Groove
// Sasha and Digweed hypnotic minimal groove
setcps(132/60/4)
let progFilter = slider(1500, 200, 5000, 10, "PROG Filter")
let groove = slider(0.6, 0, 1, 0.01, "GROOVE Depth")

let kick = s("bd").bank("RolandTR909").gain(0.9).struct("x x x x")
let rim = s("sd").bank("RolandTR909").gain(0.25).struct("~ [~ x] ~ ~").speed(1.5)
let hats = s("hh").bank("RolandTR909").gain(0.35).struct("x [x x] x [x x]").cutoff(4000)

let bassline = note("<c2 c2 c2 eb2 c2 c2 g1 ab1>")
  .s("sawtooth")
  .cutoff(perlin.range(200, progFilter).slow(8))
  .resonance(12)
  .decay(0.2)
  .sustain(0.05)
  .gain(groove.mul(0.7))
  .struct("x ~ x [~ x] x ~ x ~")

let deepPad = note("<[c3,g3] [eb3,bb3] [ab2,eb3] [bb2,f3]>".slow(4))
  .s("gm_pad_sweep")
  .gain(groove.mul(0.3))
  .cutoff(perlin.range(400, 2000).slow(16))
  .room(0.8)
  .size(0.85)

stack(kick, rim, hats, bassline, deepPad)

// DJ OPUS - SECTION 7: PROGRESSIVE OUTRO
// Sasha closing set. Hypnotic. Drifting. Beautiful.
setcps(134/60/4)

let driftFilter = slider(1500, 200, 4000, 10, "DRIFT Filter")
let fadeOut = slider(0.7, 0, 1, 0.01, "FADE Level")

// Kick - softer now
let kick = s("bd").bank("RolandTR909")
  .gain(fadeOut.mul(0.85))
  .struct("x x x x")

// Minimal hats
let hats = s("hh").bank("RolandTR909")
  .gain(fadeOut.mul(0.3))
  .struct("~ x ~ x ~ x ~ x")
  .cutoff(3000)

// Rim click
let rim = s("sd").bank("RolandTR909")
  .gain(fadeOut.mul(0.2))
  .struct("~ [~ x] ~ ~")
  .speed(1.5)

// Hypnotic bass - perlin drift, never repeats
let bass = note("<a2 a2 a2 e2 a2 a2 g2 e2>")
  .s("sawtooth")
  .cutoff(perlin.range(200, driftFilter).slow(8))
  .resonance(12)
  .decay(0.2)
  .sustain(0.05)
  .gain(fadeOut.mul(0.55))
  .struct("x ~ x [~ x] x ~ x ~")

// Last diva echo - fading into the distance
let divaEcho = note("<[a3,e4] [e3,b3]>".slow(4))
  .s("gm_voice_oohs")
  .gain(fadeOut.mul(0.3))
  .room(1)
  .size(1)
  .delay(0.6)
  .delaytime(0.5)
  .delayfeedback(0.55)
  .cutoff(driftFilter)

// Deep pad - last warmth
let deepPad = note("<[a2,e3] [e2,b2] [a2,e3] [e2,b2]>".slow(4))
  .s("gm_pad_sweep")
  .gain(fadeOut.mul(0.25))
  .cutoff(perlin.range(300, 1500).slow(16))
  .room(0.9)
  .size(0.95)

// Distant crystal - final sparkle
let crystal = note("a5 ~ ~ ~ ~ ~ ~ ~".slow(2))
  .s("gm_fx_crystal")
  .gain(fadeOut.mul(0.08))
  .delay(0.8)
  .delaytime(0.5)
  .delayfeedback(0.7)
  .room(1)

stack(kick, hats, rim, bass, divaEcho, deepPad, crystal)

// Sasha at Twilo - Late Night Progressive
// 132 BPM | G minor | Deep, hypnotic, filtered

let kickVol = slider(0.8, 0, 1, 0.01, "Kick")
let bassVol = slider(0.6, 0, 1, 0.01, "Bass")
let hatVol = slider(0.35, 0, 1, 0.01, "Hats")
let arpVol = slider(0.45, 0, 1, 0.01, "Arp")
let padVol = slider(0.55, 0, 1, 0.01, "Pad")
let leadVol = slider(0, 0, 1, 0.01, "Lead")
let filterPos = slider(1500, 200, 4000, 10, "Filter")

setcps(132/60/4)

let kick = stack(
  s("bd").bank("RolandTR909").struct("x x x x"),
  s("cp").bank("RolandTR909").struct("~ x ~ x")
).gain(kickVol)

let bass = note("<g2 g2 eb2 eb2 bb2 bb2 f2 f2>")
  .struct("x ~ [~ x] x ~ x [~ x] ~")
  .s("sawtooth")
  .cutoff(perlin.range(250, 1200).slow(16))
  .resonance(14)
  .decay(0.2).sustain(0.08).release(0.3)
  .gain(bassVol)
  .room(0.25)

let hats = s("hh*8").bank("RolandTR707")
  .gain(hatVol)
  .room(0.15)

let arp = note("g4 d5 bb4 g5 d5 bb4 f5 d5")
  .s("triangle")
  .cutoff(perlin.range(600, 2800).slow(12))
  .decay(0.12).sustain(0.03).release(0.35)
  .delay(0.4).delaytime(3/8).delayfeedback(0.5)
  .gain(arpVol)
  .room(0.5)

let pad = note("<[g3,bb3,d4] [g3,bb3,d4] [g3,bb3,eb4] [g3,bb3,eb4] [f3,bb3,d4] [f3,bb3,d4] [f3,a3,c4] [f3,a3,c4]>")
  .s("sawtooth")
  .cutoff(perlin.range(300, 1800).slow(24))
  .resonance(5)
  .attack(1.0).decay(0.5).sustain(0.7).release(2.0)
  .vowel("<a a e e i i o o>")
  .room(0.85).size(0.9)
  .jux(rev)
  .gain(padVol)

let lead = note("g4 ~ bb4 ~ d5 ~ c5 bb4 ~ a4 ~ g4 ~ f4 d4 ~").slow(2)
  .s("sawtooth")
  .superimpose(x => x.add(0.08))
  .superimpose(x => x.add(-0.08))
  .cutoff(filterPos)
  .resonance(8)
  .decay(0.3).sustain(0.15).release(0.8)
  .delay(0.4).delaytime(3/8).delayfeedback(0.55)
  .room(0.7).size(0.8)
  .jux(rev)
  .gain(leadVol)

stack(kick, bass, hats, arp, pad, lead)

// DJ OPUS - SECTION 5: THE RISE
// Building from nothing to everything
setcps(138/60/4)

let riseFilter = slider(600, 200, 12000, 10, "RISE Filter")
let tension = slider(0.2, 0, 1, 0.01, "TENSION")

// Diva still holding
let diva = note("<[a3,e4] [f3,c4] [d3,a3] [e3,b3]>".slow(2))
  .s("gm_voice_oohs")
  .gain(0.45)
  .room(0.9)
  .size(0.95)
  .cutoff(riseFilter)
  .vowel("<a e i o>".slow(4))

// Synth choir joining
let choir = note("<[a3,c4,e4] [f3,a3,c4] [d3,f3,a3] [e3,g3,b3]>".slow(2))
  .s("gm_synth_choir")
  .gain(tension.mul(0.4))
  .room(0.85)

// Snare roll building
let snare = s("sd").bank("RolandTR909")
  .gain(tension.mul(0.6))
  .struct("x x x x x x x x")
  .room(0.4)

// Kick ghost hits returning
let kickGhost = s("bd").bank("RolandTR909")
  .gain(tension.mul(0.5))
  .struct("x ~ ~ ~ x ~ ~ ~")

// Rising pad
let risePad = note("<a2 f2 d2 e2>".slow(2))
  .s("gm_pad_sweep")
  .gain(tension.mul(0.4))
  .cutoff(riseFilter)
  .room(0.9)
  .size(0.95)

// Noise riser
let noise = s("hh").bank("RolandTR909")
  .speed(0.1)
  .cutoff(riseFilter)
  .resonance(18)
  .gain(tension.mul(0.35))
  .room(0.95)
  .size(0.95)
  .struct("x x x x")

// Arp teasing the melody
let arp = note("a4 ~ e5 ~ c5 ~ a5 ~")
  .s("triangle")
  .cutoff(riseFilter)
  .decay(0.1)
  .sustain(0)
  .gain(tension.mul(0.25))
  .delay(0.5)
  .delaytime(3/16)
  .delayfeedback(0.5)
  .room(0.6)

stack(diva, choir, snare, kickGhost, risePad, noise, arp)
